const inp = $input.first().json;
const body = inp.body || inp;
const channelOverride = (typeof body.channel_id === 'string' && body.channel_id) ? body.channel_id : null;
const folderId = $env.GOOGLE_DRIVE_FOLDER_ID || '';
return [{ json: {
  driveBaseUrl: 'https://www.googleapis.com/drive/v3/files',
  subfolderQuery: `'${folderId}' in parents and mimeType = 'application/vnd.google-apps.folder' and trashed = false`,
  folderId,
  wpBaseUrl: $env.WP_BASE_URL || 'http://host.docker.internal:10020',
  wpAuth: 'Basic ' + Buffer.from(($env.WP_USERNAME || '') + ':' + ($env.WP_APP_PASSWORD || '')).toString('base64'),
  anthropicKey: $env.ANTHROPIC_API_KEY || '',
  slackToken: $env.SLACK_BOT_TOKEN || '',
  slackChannel: channelOverride || $env.SLACK_DEFAULT_CHANNEL || '',
} }];

const subfolderResp = $input.first().json;
const config = $('Load Config').first().json;
const subfolderIds = (subfolderResp.files || []).map(f => f.id);
const parentIds = [config.folderId, ...subfolderIds];
const parentClauses = parentIds.map(id => `'${id}' in parents`).join(' or ');
const docQuery = `(${parentClauses}) and mimeType = 'application/vnd.google-apps.document' and trashed = false`;
return [{ json: { ...config, docQuery, subfolderIds } }];

const config = $('Load Config').first().json;
const files = $input.first().json.files || [];

const state = $getWorkflowStaticData('global');
state.processed = state.processed || {};

const newDocs = [];
for (const file of files) {
  const prev = state.processed[file.id];
  if (prev && prev.modifiedTime === file.modifiedTime && !prev.processing) continue;
  state.processed[file.id] = {
    modifiedTime: file.modifiedTime,
    processing: true,
    startedAt: new Date().toISOString(),
  };
  newDocs.push({
    fileId: file.id,
    fileName: file.name,
    modifiedTime: file.modifiedTime,
    ...config,
  });
}

if (newDocs.length === 0) return [];
return newDocs.map(d => ({ json: d }));

const doc = $input.first().json;
const ctx = $('Prepare Doc URL').first().json;

function extractText(bodyContent) {
  let text = '';
  for (const el of (bodyContent || [])) {
    if (el.paragraph) {
      for (const run of (el.paragraph.elements || [])) {
        if (run.textRun) text += run.textRun.content;
      }
    }
    if (el.table) {
      for (const row of (el.table.tableRows || [])) {
        for (const cell of (row.tableCells || [])) {
          text += extractText(cell.content) + '\t';
        }
        text += '\n';
      }
    }
  }
  return text.trim();
}

let contentText = '';
let metadataText = '';
const tabs = doc.tabs || [];

if (tabs.length === 0) {
  contentText = extractText(doc.body?.content);
} else {
  for (const tab of tabs) {
    const title = (tab.tabProperties?.title || '').toLowerCase();
    const text = extractText(tab.documentTab?.body?.content);
    if (title.includes('metadata') || title.includes('meta data')) {
      metadataText = text;
    } else if (!contentText) {
      contentText = text;
    }
  }
}

if (!contentText || contentText.length < 50) return [];

let brief = '=== CONTENT ===\n' + contentText;
if (metadataText) brief += '\n\n=== METADATA ===\n' + metadataText;

const systemPrompt = 'You are a content analyst for Aera Technology\'s WordPress site. Determine the best Custom Post Type and extract structured fields.\n\nAvailable CPTs:\n- blog: resource_card_title, resource_excerpt, resource_cta_text. Has post body editor.\n- press-release: press_release_publication, resource_card_title, resource_excerpt. Has post body editor.\n- case-study: case_study_company_name, case_study_industry, case_study_type, case_study_business_problem, case_study_business_statement, resource_card_title, resource_excerpt. No post body.\n- whitepaper: resource_card_title, resource_excerpt, resource_external_url. No post body.\n- news: resource_card_title, resource_excerpt, resource_external_url. No post body.\n- video: video_type, video_url, resource_card_title, resource_excerpt. No post body.\n- podcast: podcast_type, podcast_video, resource_card_title, resource_excerpt. No post body.\n- report: resource_card_title, resource_excerpt, resource_external_url. No post body.\n\nIf a METADATA section is present, use it as the authoritative source for title, slug, resource_card_title, and resource_excerpt.\n\nRespond ONLY with valid JSON (no markdown):\n{\n  "cpt": "the-cpt-slug",\n  "title": "Post title",\n  "slug": "url-slug",\n  "author_name": "Full author name or empty string",\n  "excerpt": "SEO meta description ~155 chars",\n  "content": "HTML body (only if CPT has editor, else empty string)",\n  "acf": { "field": "value" },\n  "reasoning": "One sentence explaining CPT choice"\n}';

return [{ json: {
  ...ctx,
  brief,
  claudeRequestBody: {
    model: 'claude-sonnet-4-20250514',
    max_tokens: 8192,
    system: systemPrompt,
    messages: [{ role: 'user', content: brief }],
  },
} }];

const raw = $input.first().json.content?.[0]?.text || '';
const ctx = $('Extract and Build Prompt').first().json;

const cleaned = raw.replace(/^```(?:json)?\n?/i, '').replace(/\n?```$/i, '').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch(e) {
  throw new Error('Invalid JSON from Claude: ' + raw.slice(0, 200));
}

const cpt = parsed.cpt || 'blog';
const slug = (parsed.slug || '').split('/').pop();

const wpBody = {
  title: parsed.title || 'Untitled',
  slug,
  content: parsed.content || '',
  excerpt: parsed.excerpt || '',
  status: 'draft',
  acf: parsed.acf || {},
};

return [{ json: {
  ...ctx,
  cpt,
  title: parsed.title || 'Untitled',
  reasoning: parsed.reasoning || '',
  authorName: parsed.author_name || '',
  wpUrl: ctx.wpBaseUrl + '/wp-json/wp/v2/' + cpt,
  wpBodyJson: JSON.stringify(wpBody),
} }];

const wpPost = $input.first().json;
const ctx = $('Parse Claude Response').first().json;

const postId = wpPost.id;
const postTitle = (wpPost.title?.rendered || wpPost.title?.raw || ctx.title || 'Draft').trim();
const wpAdminUrl = ctx.wpBaseUrl.replace('host.docker.internal', 'localhost');
const editLink = wpAdminUrl + '/wp-admin/post.php?post=' + postId + '&action=edit';

const state = $getWorkflowStaticData('global');
state.processed = state.processed || {};
state.processed[ctx.fileId] = {
  modifiedTime: ctx.modifiedTime,
  postId,
  cpt: ctx.cpt,
  title: postTitle,
  processedAt: new Date().toISOString(),
};

const cptLabels = {
  blog: 'Blog', 'press-release': 'Press Release', 'case-study': 'Case Study',
  whitepaper: 'Whitepaper', news: 'News', video: 'Video', podcast: 'Podcast', report: 'Report',
};

let details = '*Source:* ' + ctx.fileName;
if (ctx.authorName) details += '\n*Author:* ' + ctx.authorName;
if (ctx.reasoning) details += '\n_' + ctx.reasoning + '_';

return [{ json: {
  channel: ctx.slackChannel,
  slackToken: ctx.slackToken,
  text: 'Draft created from Google Docs: ' + postTitle,
  blocks: [
    { type: 'header', text: { type: 'plain_text', text: '\u2705 Draft from Google Drive', emoji: true } },
    { type: 'section', fields: [
      { type: 'mrkdwn', text: '*Title:*\n' + postTitle },
      { type: 'mrkdwn', text: '*Type:*\n' + (cptLabels[ctx.cpt] || ctx.cpt) },
    ]},
    { type: 'section', text: { type: 'mrkdwn', text: details } },
    { type: 'section', text: { type: 'mrkdwn', text: '<' + editLink + '|Edit in WordPress>' } },
  ],
} }];
